const path = require('path');
const fs = require('fs');
const { withPage, wrapArtifact } = require('/tmp/claude-0/-home-user-CogSci-Projects/69c5220c-1e8f-53c6-a773-1de29f533ec2/scratchpad/test/harness.js');
