const SHOTS = path.join(A, 'shots'); fs.mkdirSync(SHOTS, { recursive: true });
const URL_INDEX = 'file://' + path.join(GAME_DIR, 'index.html');
const WRAPPED = path.join(GAME_DIR, 'artifact.wrapped.html'); // must sit next to cards.js/game.js for the relative script tags; removed at the end
const URL_ART = 'file://' + wrapArtifact(path.join(GAME_DIR, 'artifact.html'), WRAPPED);
const results = [];
let section = '';
function check(name, ok, info) { results.push({ name: section + name, ok: !!ok }); if (!ok) console.log('  FAIL ' + section + name + (info !== undefined ? ' :: ' + JSON.stringify(info) : '')); else console.log('  ok   ' + section + name); }
const shot = async (page, name) => { await page.evaluate(() => document.querySelectorAll('.toast').forEach((t) => t.remove())); await page.waitForTimeout(350); await page.screenshot({ path: path.join(SHOTS, name + '.png'), fullPage: false }); }; // toasts never time out while the test clock is frozen; the wait lets CSS transitions (lab drawer, sheets) settle
const noHScroll = (page) => page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1 && document.getElementById('app').scrollWidth <= document.getElementById('app').clientWidth + 1 && Array.from(document.querySelectorAll('.screen.active')).every((s) => s.scrollWidth <= s.clientWidth + 1));
const activeScreen = (page) => page.evaluate(() => (document.querySelector('.screen.active') || {}).dataset ? document.querySelector('.screen.active').dataset.screen : null);
// The A-10.6 fixture: seed 1, pinned A/B buckets, pinned inputs, choreography collapsed, onboarding skipped.
const setupSmoke = (page) => page.evaluate(() => { GAME.reset(); GAME.seed(1); GAME.setExperiment({ T0: 4.0, declineDelayMs: 1200, sliverPct: 0.05, postAdBoost: 1.10 }); GAME.setModel({ inputs: { deviceTier: 0.7, region: 1 / 3, hourMul: 0.7 } }); GAME.skipAnims(true); GAME.finishOnboarding(); GAME.CONST.patience.idleMs = 3600000; GAME.freezeTime(true); window.cont = () => { const c = document.querySelector('.screen.active [data-act="continue"]'); if (c) c.click(); const ad = GAME.currentAd(); if (ad && ad.format === 'interstitial') { GAME.fastForward(5000); GAME.closeAd('x'); } }; window.home = () => { GAME.goto('home'); cont(); }; });
const top3 = () => { const st = GAME.getState(); return Object.keys(st.collection).map((id) => { const c = GAME.cards.find((x) => x.id === id); return { id, p: Math.round({ C: 220, U: 245, R: 275, H: 310, L: 350 }[c.rarity] * (1 + 0.04 * Math.min(st.collection[id] - 1, 5))) }; }).sort((a, b) => b.p - a.p || a.id.localeCompare(b.id)).slice(0, 3).map((x) => x.id); };

