  const lb = await page.evaluate(() => { GAME.lab(true); const out = {}; const lab = document.getElementById('lab'); out.sections = lab.querySelectorAll('.lp').length; out.sentence = lab.querySelector('.lp:nth-child(4) .sentence').textContent; out.sentenceOk = /^(CLEAN|NORMAL|KILL|REWARD|COOLDOWN|ONBOARD): opponent generated at tier \d+ while the card said rung \d+; \d+ of your \d+ rolls were (best|worst)-of-two \(mean [\d.]+ vs opponent [\d.]+; honest 0\.925\); the opponent crit \d+× at [\d.]+%; AI q = [\d.]+; (no bait|bait armed but not fired|bait fired on turn \d+, leaving \d+% HP); damage ×[\d.]+( after the revive)?\.$/.test(out.sentence); out.res = lab.querySelector('.kv.res') && lab.querySelector('.kv.res').textContent; out.resOk = /Same opponent, fair dice: (WIN|LOSS) on turn \d+ \(\d+ of \d+ actions replayed\)\. Honest-rung opponent: (WIN|LOSS)\./.test(out.res); const rp = GAME.replayFair(); out.rp = rp; out.rpOk = rp.sameOpponent.replayed + rp.sameOpponent.substituted === rp.recorded && JSON.stringify(rp) === JSON.stringify(GAME.replayFair()); out.gauge = lab.textContent.includes('adValue') && lab.textContent.includes('simulated proxy') && lab.textContent.includes('kill line') && lab.textContent.includes('$ per minute of your attention'); document.querySelector('[data-act="lab-export-turns"]').click(); out.exportModal = !!document.querySelector('textarea.export'); document.querySelector('.modal [data-dlg]').click(); document.querySelector('[data-act="lab-about"]').click(); out.memo = lab.textContent.includes('ARPDAU $0.11') && lab.textContent.includes('recognised as'); document.getElementById('lab-filter').value = 'bait'; document.getElementById('lab-filter').dispatchEvent(new Event('input', { bubbles: true })); return out; });
  check('lab panels: last-battle sentence with every placeholder filled; replay-fair result line; replayFair deterministic with replayed + substituted == recorded; gauges and proxies; export modal; About the machine memo', lb.sections === 8 && lb.sentenceOk && lb.resOk && lb.rpOk && lb.gauge && lb.exportModal && lb.memo, lb);
  const lo = await page.evaluate(() => { const out = {}; document.getElementById('lab-T').value = '6'; document.querySelector('[data-act="lab-set-T"]').click(); out.T = GAME.getModel().T; out.ov = GAME.getLog('lab.override').pop().data; document.getElementById('lab-phase').value = 'NORMAL'; document.querySelector('[data-act="lab-set-phase"]').click(); out.phase = GAME.getModel().phase; document.getElementById('lab-seg').value = 'WATCHER'; document.querySelector('[data-act="lab-set-seg"]').click(); out.seg = GAME.getModel().segment; const input = document.querySelector('#lab .evlog .ev'); out.filtered = !!input && input.textContent.includes('bait'); return out; });
  check('lab overrides: set T (lab.override{what:T}), force phase, set segment; event-log filter works', lo.T === 6 && lo.ov.what === 'T' && lo.phase === 'NORMAL' && lo.seg === 'WATCHER', lo);
  check('no horizontal scroll with the lab open', await noHScroll(page));
  if (variant === 'index') await shot(page, 'lab');
  await page.evaluate(() => GAME.lab(false));

  // ---------------------------------------------------------------- an ordinary battle with the full choreography (real UI taps through the trainer card)
  section = variant + ' · battle UI: ';
  await setupSmoke(page);
  await page.evaluate(() => { GAME.skipAnims(false); GAME.setPhase('CLEAN'); document.querySelector('.battle-btn').click(); });
  check('BATTLE button starts a battle on the battle screen with the trainer card sliding in (rival name, rung, three mini-cards)', await page.evaluate(() => document.querySelector('.screen.active').dataset.screen === 'battle' && !!document.querySelector('.trainer') && document.querySelector('.trainer .t-sub').textContent.includes('Rung 2') && document.querySelectorAll('.trainer .card.mini').length === 3));
  await page.evaluate(() => GAME.fastForward(2500));
  if (variant === 'index') { await page.evaluate(() => { document.querySelector('.move[data-act="move:0"]').click(); GAME.fastForward(260); }); await shot(page, 'battle'); }
  const ub = await page.evaluate(() => { let guard = 0; while (GAME.getBattle().state !== 'END' && guard++ < 60) { GAME.fastForward(8000); const m = document.querySelector('.move[data-act="move:0"]'); const bs = document.querySelector('.bs-card:not(.out)'); if (m) m.click(); else if (bs) bs.click(); } GAME.fastForward(8000); return { result: GAME.getBattle().result, turns: GAME.getBattle().turns.length, stamp: document.querySelector('.stamp') && document.querySelector('.stamp').textContent, results: !!document.querySelector('.results'), bob: !!document.querySelector('.spr.player[class*="bob-"]') }; });
  check('full battle through taps with real choreography driven by the virtual clock; results card at the end', ub.result && ub.results && (ub.result !== 'win' || ub.stamp === 'VICTORY') && ub.turns >= 2 && ub.bob, ub);
  await page.evaluate(() => { GAME.skipAnims(true); const c = document.querySelector('[data-act="continue"]'); if (c) c.click(); });

  // ---------------------------------------------------------------- persistence (reload), save upgrade, live-battle abandonment, reset
  section = variant + ' · persistence: ';
  await setupSmoke(page);
  await page.evaluate(() => GAME.setNow(Date.now())); // a reload runs on the real clock again
  const before = await page.evaluate(() => { GAME.startBattle({ rung: 2 }); GAME.autoBattle(); if (GAME.pendingOffer()) GAME.respondOffer(false); cont(); GAME.openPack({ instant: true, free: true }); GAME.setPhase('NORMAL'); const s = GAME.getState(), m = GAME.getModel(); return { collection: s.collection, team: s.team, coins: s.coins, focus: s.focus, ladder: s.ladder, phase: m.phase, F: m.F, T: m.T, segment: m.segment, revenue: m.revenue, log: GAME.getLog().length, lastSeq: GAME.getLog().pop().seq, rng: GAME.rngCursors(), seed: s.seed }; });
  await page.waitForTimeout(400);
  await page.reload({ waitUntil: 'load' }); await page.waitForTimeout(250);
  const after = await page.evaluate(() => { const s = GAME.getState(), m = GAME.getModel(); return { collection: s.collection, team: s.team, coins: s.coins, focus: s.focus, ladder: s.ladder, phase: m.phase, F: m.F, T: m.T, segment: m.segment, revenue: m.revenue, log: GAME.getLog().length, keptSeq: GAME.getLog()[GAME.getLog().length - 4] && GAME.getLog()[GAME.getLog().length - 4].seq, rng: GAME.rngCursors(), seed: s.seed, screen: document.querySelector('.screen.active').dataset.screen, resumed: GAME.getLog('session.start').pop().data.resumed, boot: GAME.getLog().slice(-3).map((e) => e.type) }; });
  check('reload keeps collection, team, coins, Focus, ladder, phase, F, T, segment, revenue, the log (plus the boot entries) and the three RNG cursors', ['collection', 'team', 'coins', 'focus', 'ladder', 'phase', 'F', 'T', 'segment', 'revenue', 'rng', 'seed'].every((k) => JSON.stringify(before[k]) === JSON.stringify(after[k])) && after.log === before.log + 3 && after.keptSeq === before.lastSeq && after.boot.join() === 'model.update,session.start,fomo.view' && after.screen === 'home' && after.resumed === true, { before, after });
